export function Shell({ children, user, badges = {}, notifications = [], extraNav, cyrus }: {
  children: React.ReactNode; user: User; badges?: Badges; notifications?: Note[];
  /** Cyrus top-bar entry + pinned token balance, resolved server side (null = not for this viewer). */
  cyrus?: { beta: boolean } | null;
  /** Per-user rail entries (private previews), resolved server side. */
  extraNav?: NavItem[];
}) {
  // The composer lives at the SHELL level, exactly as it does in the portal
  // shell this one replaces. Two reasons it cannot move down into the mail
  // page: App Router keeps the shell mounted across in-portal navigation, so an
