import { useEffect, useState, type JSX, type SVGProps } from "react";
import type { ModelId } from "@/lib/cyrus/types";

/**
 * Cyrus model glyphs (v6): one tier language for Katara, Saka and Yakko, the models' original
 * names. Each is a cluster of forge crystals: Katara one, Saka two, Yakko three. Same 24-unit grid,
 * same 1.5 outline, same facet line, so they read as a set and the tier is the number of crystals.
 *
 *  - variant "gradient": the brand version (each model's own cyan / indigo / magenta ramp with a
 *    white edge light). Used in the model picker, the plans cards, the prompt dock, the token chip.
 *  - variant "mono": currentColor outline + 20% fill, for tinted chips and small inline marks.
 *
 * Standalone copies of the same paths: public/cyrus/models/{katara,saka,yakko}.svg (gradient) and
 * {id}-mono.svg (currentColor). The marketing page imports this component or those files.
 */

type Crystal = { outline: string; facet: string };

export const MODEL_CRYSTALS: Record<ModelId, Crystal[]> = {
  katara: [{ outline: "M8.3 20.1L8.3 8.4L12 3.6L15.7 8.4L15.7 20.1L12 21Z", facet: "M12 3.6L11.41 9.6L12 20.4" }],
