    { outline: "M15.57 18.26L18.83 12.62L21.94 11.27L22.33 14.64L19.08 20.28L16.93 19.96Z", facet: "M21.94 11.27L19.77 14.38L17.19 19.5" },
    { outline: "M9.54 19.16L9.54 7.81L12 4.29L14.46 7.81L14.46 19.16L12 19.96Z", facet: "M12 4.29L11.61 8.87L12 19.43" },
  ],
};

/** Each model's gradient ramp (light top, model hue, deep base). */
export const MODEL_RAMP: Record<ModelId, [string, string, string]> = {
  katara: ["#d6fdff", "#22d3ee", "#1e40af"],
  saka: ["#e6e9ff", "#818cf8", "#4c1d95"],
  yakko: ["#ffe4f8", "#e879f9", "#701a75"],
};

let seq = 0;

export type ModelGlyphVariant = "gradient" | "mono";
type P = Omit<SVGProps<SVGSVGElement>, "id"> & { size?: number | string; variant?: ModelGlyphVariant; title?: string };

/** Renders the mark for a Cyrus model. Size defaults to 1em, like the other studio icons. */
export function ModelGlyph({ id, size = "1em", variant = "gradient", title, className, ...props }: { id: ModelId } & P) {
  const crystals = MODEL_CRYSTALS[id] ?? MODEL_CRYSTALS.saka;
  // The gradient id: a stable one for the server render and hydration (a useId() differed
  // server/client inside the portal frame, see ThinkingBrain), then a unique one per instance after
  // mount. A shared id breaks every copy in Chrome when the first one sits in a display:none
  // subtree (the token chip's hover card on touch screens, sm:hidden variants).
  const [gid, setGid] = useState(`cyrus-model-${id}-g`);
  useEffect(() => setGid(`cyrus-model-${id}-g${++seq}`), [id]);
  const ramp = MODEL_RAMP[id] ?? MODEL_RAMP.saka;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill="none"
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={`cy-model-glyph ${className ?? ""}`}
      data-model={id}
      data-variant={variant}
      {...props}
    >
      {variant === "gradient" ? (
        <>
          <defs>
            <linearGradient id={gid} x1="6" y1="3" x2="17" y2="22" gradientUnits="userSpaceOnUse">
              <stop offset="0" stopColor={ramp[0]} />
              <stop offset=".48" stopColor={ramp[1]} />
              <stop offset="1" stopColor={ramp[2]} />
            </linearGradient>
          </defs>
          {crystals.map((c, i) => (
            <g key={i} strokeLinejoin="round">
              <path d={c.outline} fill={`url(#${gid})`} stroke={`url(#${gid})`} strokeWidth={0.9} />
              <path d={c.outline} stroke="#fff" strokeOpacity={0.5} strokeWidth={0.55} />
              <path d={c.facet} stroke="#fff" strokeOpacity={0.7} strokeWidth={0.7} strokeLinecap="round" />
            </g>
          ))}
        </>
      ) : (
        crystals.map((c, i) => (
          <g key={i} stroke="currentColor" strokeLinejoin="round">
            <path d={c.outline} fill="currentColor" fillOpacity={0.2} strokeWidth={1.5} />
            <path d={c.facet} strokeOpacity={0.7} strokeWidth={1} strokeLinecap="round" />
          </g>
        ))
      )}
    </svg>
  );
}

export const KataraGlyph = (p: P) => <ModelGlyph id="katara" {...p} />;
export const SakaGlyph = (p: P) => <ModelGlyph id="saka" {...p} />;
export const YakkoGlyph = (p: P) => <ModelGlyph id="yakko" {...p} />;
export const MODEL_GLYPHS: Record<ModelId, (p: P) => JSX.Element> = { katara: KataraGlyph, saka: SakaGlyph, yakko: YakkoGlyph };
