"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { MARK_ARM, MARK_SWEEP, MARK_VIEWBOX } from "@/components/cyrus/icons/cyrusMark";
import { Logo } from "./Logo";

/** The Cyrus "Y" mark in one ink (currentColor): same paths as the brand mark, no gradients. */
export function CyrusMarkSolid({ height = 14, className = "" }: { height?: number; className?: string }) {
  return (
    <svg viewBox={MARK_VIEWBOX} height={height} width={(height * 940) / 520} aria-hidden focusable="false" className={className}>
      <path d={MARK_SWEEP} fill="currentColor" />
      <path d={MARK_ARM} fill="currentColor" />
    </svg>
  );
}

/** Light-mode selector for the portal (data-theme on <html>). The header stays a dark island, so the inverse pill keeps a hairline. */
const LIGHT = "[html[data-theme=light]_&]";

/**
 * Cyrus' entry in the Nxeon top bar: a different product, so it is a plain inverse pill (white with the black mark;
 * black with the white mark in light mode). Opens Cyrus full screen (components/nx/Shell.tsx drops the portal chrome
 * on /dashboard/cyrus). No token balance here: Cyrus shows its own inside the studio.
 */
export function CyrusTopEntry({ beta }: { beta: boolean }) {
  return (
    <Link
      href="/dashboard/cyrus"
      aria-label="Open Cyrus, the AI mod studio"
      title="Cyrus: describe a mod, get a working Minecraft plugin"
      data-cyrus-entry
      className={`inline-flex h-9 flex-none items-center gap-2 rounded-full bg-white px-3 text-[13px] font-bold text-black shadow-[0_1px_0_rgba(255,255,255,.4)_inset,0_6px_18px_-10px_rgba(0,0,0,.9)] transition hover:-translate-y-px hover:bg-white/90 sm:px-3.5 ${LIGHT}:bg-black ${LIGHT}:text-white ${LIGHT}:ring-1 ${LIGHT}:ring-white/25 ${LIGHT}:hover:bg-black/85`}
    >
      <CyrusMarkSolid height={12} />
      <span className="hidden sm:inline">Cyrus</span>
      {beta && <span className={`hidden rounded-full bg-black/10 px-1.5 py-px text-[9px] font-extrabold tracking-wider md:inline ${LIGHT}:bg-white/20`}>BETA</span>}
    </Link>
  );
}

/**
 * The only Nxeon chrome left while Cyrus is open full screen: a slim strip with one way back to the page the user
 * came from in the portal (falls back to /dashboard).
 */
export function CyrusBackBar({ href }: { href: string }) {
  return (
    <div
      data-cyrus-backbar
      className={`relative z-30 flex h-9 flex-none items-center border-b border-white/10 bg-[#05060a] px-2 sm:px-3 ${LIGHT}:border-black/10 ${LIGHT}:bg-[#f3f4f7]`}
    >
      <Link
        href={href}
        className={`inline-flex h-7 items-center gap-1.5 rounded-full border border-white/15 bg-white/[.04] pl-1.5 pr-3 text-[12px] font-semibold text-white/80 transition hover:border-white/30 hover:text-white ${LIGHT}:border-black/15 ${LIGHT}:bg-white ${LIGHT}:text-black/75 ${LIGHT}:hover:text-black`}
      >
        <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M10 3.5 5.5 8l4.5 4.5" /></svg>
        <Logo size={16} />
        <span>Back to Nxeon</span>
      </Link>
    </div>
  );
}

