// Free-build abuse guard for the one-time starter grant: one grant per real person, not per sign-up.
//   - normalizeEmail: dots/+tags/googlemail variants collapse to one identity, so alias accounts share one grant.
//   - isDisposableEmail: throwaway-inbox domains never receive the free build (they can still buy tokens).
// Pure (unit-tested without any framework imports). The disposable list is a baseline, not exhaustive: extend it
// from real abuse in /admin/cyrus. Per-IP/device caps need request context and storage and are a separate step.
import { createHash } from "node:crypto";

const DISPOSABLE = new Set([
  "mailinator.com", "guerrillamail.com", "guerrillamail.net", "guerrillamail.org", "guerrillamail.biz", "guerrillamailblock.com", "sharklasers.com",
  "grr.la", "pokemail.net", "spam4.me", "10minutemail.com", "10minutemail.net", "20minutemail.com", "tempmail.com", "temp-mail.org", "temp-mail.io",
  "tempail.com", "tempmailo.com", "tmpmail.org", "tmpmail.net", "yopmail.com", "yopmail.net", "yopmail.fr", "trashmail.com", "trashmail.net",
  "trashmail.de", "getnada.com", "nada.email", "dispostable.com", "maildrop.cc", "throwawaymail.com", "fakeinbox.com", "mintemail.com", "mohmal.com",
  "emailondeck.com", "moakt.com", "mailnesia.com", "inboxkitten.com", "burnermail.io", "mytemp.email", "tempinbox.com", "discard.email", "mailcatch.com",
  "spamgourmet.com", "33mail.com", "getairmail.com", "mail.tm", "1secmail.com", "1secmail.net", "emailfake.com", "fakemail.net", "tempr.email",
  "dropmail.me", "harakirimail.com", "mailpoof.com", "mvrht.net", "my10minutemail.com", "owlymail.com", "spambox.us", "tafmail.com", "emltmp.com",
]);

const domainOf = (email: string): string => email.trim().toLowerCase().split("@")[1] ?? "";

/** True for known throwaway-inbox domains and their subdomains. */
export function isDisposableEmail(email: string): boolean {
  const d = domainOf(email);
  if (!d) return false;
  const parts = d.split(".");
  for (let i = 0; i < parts.length - 1; i++) if (DISPOSABLE.has(parts.slice(i).join("."))) return true;
  return false;
}

/** One identity per inbox: lowercase, drop +tags, and for Gmail also drop dots and map googlemail.com -> gmail.com. */
export function normalizeEmail(email: string): string {
  const e = email.trim().toLowerCase();
  const at = e.lastIndexOf("@");
  if (at < 1) return e;
  let local = e.slice(0, at).split("+")[0];
  let domain = e.slice(at + 1);
  if (domain === "googlemail.com") domain = "gmail.com";
  if (domain === "gmail.com") local = local.replace(/\./g, "");
  return `${local}@${domain}`;
}

export type StarterEligibility = { ok: true; key: string } | { ok: false; reason: "no_email" | "disposable" };

/** Whether this email may receive the starter grant, and the stable dedupe key (hash of the normalized email). */
export function starterEligibility(email: string | null | undefined): StarterEligibility {
  if (!email || !email.includes("@")) return { ok: false, reason: "no_email" };
  if (isDisposableEmail(email)) return { ok: false, reason: "disposable" };
  return { ok: true, key: createHash("sha256").update(normalizeEmail(email)).digest("hex").slice(0, 32) };
}

// Cyrus token ledger: the ONLY code that moves tokens. Server only; plain module
// (safe in the worker). See docs/DOCUMENTATION.md "Cyrus token economy".
//
// Invariants:
//  - Every write runs in one transaction that first locks the account row (FOR UPDATE),
//    so all of one account's token operations are serialised.
//  - CyrusTokenLedger is append-only; `idemKey` is UNIQUE. An operation whose key already
//    exists is a no-op that reports `created: false` (webhook retries, re-runs, double clicks).
//  - Balance = SUM(lot.remaining) over unexpired lots. Due lots are expired (with a ledger
//    row) at the start of every operation, so a stale lot is never spent.
//  - Reserving moves nothing: it only raises `reserved`. Settling spends the ACTUAL cost
//    from lots (soonest-expiring first) and drops the hold. Nothing goes below zero; a cost
//    above what the account holds is recorded as a write-off (Nxeon absorbs it).
import { Prisma } from "@prisma/client";
import { cyrusDb as db } from "../db";

export type Tx = Prisma.TransactionClient;
const DAY = 86_400_000;

export type LedgerKind = "grant" | "purchase" | "reserve" | "spend" | "release" | "refund" | "expire" | "revoke";
export type LotSource = "server_initial" | "server_renewal" | "plan" | "topup" | "admin" | "refund";

class Duplicate extends Error {}

function isUniqueViolation(e: unknown): boolean {
  return (e as { code?: string })?.code === "P2002";
}

async function lock(tx: Tx, userId: string): Promise<{ createdAt: Date }> {
  await tx.$executeRaw`INSERT INTO "CyrusTokenAccount" ("userId", "updatedAt") VALUES (${userId}, now()) ON CONFLICT ("userId") DO NOTHING`;
  const rows = await tx.$queryRaw<{ createdAt: Date }[]>`SELECT "createdAt" FROM "CyrusTokenAccount" WHERE "userId" = ${userId} FOR UPDATE`;
  return rows[0];
}

async function sums(tx: Tx, userId: string): Promise<{ balance: number; reserved: number }> {
  const [b, r] = await Promise.all([
    tx.cyrusTokenLot.aggregate({ where: { userId, remaining: { gt: 0 } }, _sum: { remaining: true } }),
    tx.cyrusTokenReservation.aggregate({ where: { userId, status: "held" }, _sum: { amount: true } }),
  ]);
  return { balance: b._sum.remaining ?? 0, reserved: r._sum.amount ?? 0 };
}

async function store(tx: Tx, userId: string, extra: Prisma.CyrusTokenAccountUpdateInput = {}): Promise<{ balance: number; reserved: number }> {
  const s = await sums(tx, userId);
  await tx.cyrusTokenAccount.update({ where: { userId }, data: { balance: s.balance, reserved: s.reserved, ...extra } });
  return s;
}

type LedgerRow = Omit<Prisma.CyrusTokenLedgerUncheckedCreateInput, "balanceAfter" | "reservedAfter" | "userId" | "kind" | "delta" | "idemKey"> & {
  kind: LedgerKind; delta: number; idemKey: string;
};

async function writeLedger(tx: Tx, userId: string, row: LedgerRow, after: { balance: number; reserved: number }) {
  return tx.cyrusTokenLedger.create({ data: { ...row, userId, balanceAfter: after.balance, reservedAfter: after.reserved } });
}

async function exists(tx: Tx, idemKey: string) {
  return !!(await tx.cyrusTokenLedger.findUnique({ where: { idemKey }, select: { id: true } }));
}

/** Expire every due lot of this account (one ledger row per lot, idempotent per lot). */
async function expireDue(tx: Tx, userId: string, now: Date): Promise<number> {
  const due = await tx.cyrusTokenLot.findMany({ where: { userId, remaining: { gt: 0 }, expiresAt: { lte: now } }, orderBy: { expiresAt: "asc" } });
  let total = 0;
  for (const lot of due) {
    const key = `expire:${lot.id}`;
    if (await exists(tx, key)) continue;
    await tx.cyrusTokenLot.update({ where: { id: lot.id }, data: { remaining: 0 } });
    total += lot.remaining;
    const after = await sums(tx, userId);
    await writeLedger(tx, userId, { kind: "expire", delta: -lot.remaining, idemKey: key, source: lot.source, sourceRef: lot.sourceRef, lotId: lot.id, note: "expired" }, after);
  }
  if (due.length) await store(tx, userId);
  return total;
}

/** Take up to `amount` from the account's lots, soonest-expiring first. */
async function drawLots(tx: Tx, userId: string, amount: number, where: Prisma.CyrusTokenLotWhereInput = {}): Promise<{ taken: number; draws: { lotId: string; n: number }[] }> {
  if (amount <= 0) return { taken: 0, draws: [] };
  const lots = await tx.cyrusTokenLot.findMany({
    where: { userId, remaining: { gt: 0 }, ...where },
    orderBy: [{ expiresAt: { sort: "asc", nulls: "last" } }, { createdAt: "asc" }],
  });
  let left = amount;
  const draws: { lotId: string; n: number }[] = [];
  for (const lot of lots) {
    if (left <= 0) break;
    const n = Math.min(left, lot.remaining);
    await tx.cyrusTokenLot.update({ where: { id: lot.id }, data: { remaining: lot.remaining - n } });
    draws.push({ lotId: lot.id, n });
    left -= n;
  }
  return { taken: amount - left, draws };
}

async function run<T>(userId: string, fn: (tx: Tx, acct: { createdAt: Date }) => Promise<T>): Promise<T | typeof DUP> {
  try {
    return await db.$transaction(async (tx) => fn(tx, await lock(tx, userId)), { timeout: 20_000, maxWait: 10_000 });
  } catch (e) {
    if (e instanceof Duplicate || isUniqueViolation(e)) return DUP;
    throw e;
  }
}
const DUP = Symbol("duplicate");

// ---------------------------------------------------------------------------
// Credits
// ---------------------------------------------------------------------------

export type CreditInput = {
  userId: string;
  amount: number;
  kind: "grant" | "purchase" | "refund";
  source: LotSource;
  sourceRef?: string | null;
  idemKey: string;
  expiresAt?: Date | null;
  note?: string | null;
  meta?: Prisma.InputJsonValue;
  actorId?: string | null;
  now?: Date;
  /** Runs under the account lock before crediting: cap the amount (abuse limits). */
  clamp?: (tx: Tx, amount: number, now: Date) => Promise<{ amount: number; note?: string }>;
};

export type CreditResult = { created: boolean; amount: number; lotId: string | null; note?: string | null };

/** Add tokens (a new lot). Idempotent on idemKey; a zero amount still writes the row (so a capped grant is final). */
export async function creditTokens(i: CreditInput): Promise<CreditResult> {
  const now = i.now ?? new Date();
  const r = await run(i.userId, async (tx) => {
    if (await exists(tx, i.idemKey)) throw new Duplicate();
    await expireDue(tx, i.userId, now);
    let amount = Math.max(0, Math.floor(i.amount));
    let note = i.note ?? null;
    if (i.clamp) {
      const c = await i.clamp(tx, amount, now);
      if (c.amount < amount) note = [note, c.note].filter(Boolean).join("; ") || null;
      amount = Math.max(0, Math.floor(c.amount));
    }
    let lotId: string | null = null;
    if (amount > 0) {
      const lot = await tx.cyrusTokenLot.create({ data: { userId: i.userId, source: i.source, sourceRef: i.sourceRef ?? null, amount, remaining: amount, expiresAt: i.expiresAt ?? null } });
      lotId = lot.id;
    }
    const after = await store(tx, i.userId, amount > 0 ? { lifetimeGranted: { increment: amount } } : {});
    await writeLedger(tx, i.userId, { kind: i.kind, delta: amount, idemKey: i.idemKey, source: i.source, sourceRef: i.sourceRef ?? null, lotId, note, meta: i.meta, actorId: i.actorId ?? null }, after);
    return { created: true, amount, lotId, note };
  });
  if (r === DUP) {
    const prev = await db.cyrusTokenLedger.findUnique({ where: { idemKey: i.idemKey } });
    return { created: false, amount: prev?.delta ?? 0, lotId: prev?.lotId ?? null, note: prev?.note };
  }
  return r;
}

// ---------------------------------------------------------------------------
// Builds: reserve -> settle / release
// ---------------------------------------------------------------------------

export type ReserveResult =
  | { ok: true; amount: number; created: boolean; available: number }
  | { ok: false; code: "insufficient_tokens" | "daily_cap"; available: number; need: number; usedToday?: number; cap?: number };

/**
 * Hold tokens for a build. `pick(available)` returns the amount to hold (or null = not
 * enough). `dailyCap(createdAt)` bounds reserve+spend per rolling 24 h. Idempotent per buildId.
 */
export async function reserveTokens(i: {
  userId: string; buildId: string; model: string; need: number;
  pick: (available: number) => number | null;
  dailyCap: (accountCreatedAt: Date) => number;
  allowShort?: boolean;
  now?: Date;
}): Promise<ReserveResult> {
  const now = i.now ?? new Date();
  const r = await run(i.userId, async (tx, acct) => {
    const prev = await tx.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
    if (prev) return { ok: true as const, amount: prev.amount, created: false, available: 0 };
    await expireDue(tx, i.userId, now);
    const s = await sums(tx, i.userId);
    const available = Math.max(0, s.balance - s.reserved);
    let amount = i.pick(available);
    if (amount === null) {
      if (!i.allowShort) return { ok: false as const, code: "insufficient_tokens" as const, available, need: i.need };
      amount = Math.min(available, i.need);
    }
    const since = new Date(now.getTime() - DAY);
    const recent = await tx.cyrusTokenReservation.findMany({ where: { userId: i.userId, createdAt: { gt: since } }, select: { status: true, amount: true, charged: true } });
    const usedToday = recent.reduce((a, x) => a + (x.status === "held" ? x.amount : x.charged ?? 0), 0);
    const cap = i.dailyCap(acct.createdAt);
    if (!i.allowShort && usedToday + amount > cap) return { ok: false as const, code: "daily_cap" as const, available, need: amount, usedToday, cap };
    await tx.cyrusTokenReservation.create({ data: { buildId: i.buildId, userId: i.userId, model: i.model, amount, status: "held", createdAt: now } });
    const after = await store(tx, i.userId);
    await writeLedger(tx, i.userId, { kind: "reserve", delta: 0, idemKey: `reserve:${i.buildId}`, buildId: i.buildId, model: i.model, meta: { hold: amount } }, after);
    return { ok: true as const, amount, created: true, available: available - amount };
  });
  if (r === DUP) return { ok: true, amount: 0, created: false, available: 0 };
  return r;
}

export type SettleResult = { settled: boolean; charged: number; writeoff: number; released: number; reason: string };

/**
 * Finish a build's hold: spend `charge` tokens (the ACTUAL cost, decided by the caller),
 * release the rest. Idempotent: a reservation that is no longer held is returned as-is.
 */
export async function settleReservation(i: { buildId: string; charge: number; reason: string; costUsd?: number | null; now?: Date }): Promise<SettleResult | null> {
  const res = await db.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
  if (!res) return null;
  const now = i.now ?? new Date();
  const r = await run(res.userId, async (tx) => {
    const cur = await tx.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
    if (!cur || cur.status !== "held") return { settled: false, charged: cur?.charged ?? 0, writeoff: 0, released: 0, reason: "already" };
    await expireDue(tx, res.userId, now);
    const want = Math.max(0, Math.ceil(i.charge));
    const { taken, draws } = await drawLots(tx, res.userId, want);
    const writeoff = want - taken;
    await tx.cyrusTokenReservation.update({ where: { buildId: i.buildId }, data: { status: want > 0 ? "settled" : "released", charged: taken, costUsd: i.costUsd ?? null, settledAt: now } });
    const after = await store(tx, res.userId, taken > 0 ? { lifetimeSpent: { increment: taken } } : {});
    const released = Math.max(0, cur.amount - taken);
    await writeLedger(tx, res.userId, {
      kind: want > 0 ? "spend" : "release",
      delta: -taken,
      idemKey: `settle:${i.buildId}`,
      buildId: i.buildId,
      model: cur.model,
      note: i.reason,
      meta: { hold: cur.amount, released, writeoff, costUsd: i.costUsd ?? null, draws },
    }, after);
    return { settled: true, charged: taken, writeoff, released, reason: i.reason };
  });
  if (r === DUP) return { settled: false, charged: 0, writeoff: 0, released: 0, reason: "already" };
  return r;
}

// ---------------------------------------------------------------------------
// Revoke / expire / rollover
// ---------------------------------------------------------------------------

/** Remove up to `amount` unspent tokens (refunds, admin revoke). Never below zero. Idempotent. */
export async function revokeTokens(i: {
  userId: string; amount: number; idemKey: string; note?: string; actorId?: string | null; sourceRef?: string | null;
  /** Restrict to these lots (e.g. the lot a refunded invoice granted); falls back to nothing else. */
  lotIds?: string[];
  meta?: Prisma.InputJsonValue;
  now?: Date;
}): Promise<{ created: boolean; revoked: number }> {
  const now = i.now ?? new Date();
  const r = await run(i.userId, async (tx) => {
    if (await exists(tx, i.idemKey)) throw new Duplicate();
    await expireDue(tx, i.userId, now);
    // Never take tokens a running build already holds.
    const s0 = await sums(tx, i.userId);
    const free = Math.max(0, s0.balance - s0.reserved);
    const want = Math.min(Math.max(0, Math.floor(i.amount)), free);
    const { taken, draws } = await drawLots(tx, i.userId, want, i.lotIds ? { id: { in: i.lotIds } } : {});
    const after = await store(tx, i.userId);
    await writeLedger(tx, i.userId, { kind: "revoke", delta: -taken, idemKey: i.idemKey, sourceRef: i.sourceRef ?? null, note: i.note ?? null, actorId: i.actorId ?? null, meta: { requested: i.amount, draws, ...(i.meta && typeof i.meta === "object" ? (i.meta as object) : {}) } }, after);
    return { created: true, revoked: taken };
  });
  if (r === DUP) return { created: false, revoked: 0 };
  return r;
}

/** Shorten the expiry of an account's lots of one source (a plan ended). Not a token move. */
export async function capLotExpiry(userId: string, source: LotSource, expiresAt: Date): Promise<number> {
  const r = await db.cyrusTokenLot.updateMany({
    where: { userId, source, remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: expiresAt } }] },
    data: { expiresAt },
  });
  return r.count;
}

/** Expire due lots for one account (or every account with due lots). */
export async function expireDueLots(userId?: string, now = new Date()): Promise<number> {
  const users = userId
    ? [userId]
    : (await db.cyrusTokenLot.findMany({ where: { remaining: { gt: 0 }, expiresAt: { lte: now } }, select: { userId: true }, distinct: ["userId"], take: 500 })).map((x) => x.userId);
  let total = 0;
  for (const u of users) {
    const r = await run(u, async (tx) => expireDue(tx, u, now));
    if (r !== DUP) total += r;
  }
  return total;
}

