model CyrusTokenLedger {
  id           String   @id @default(cuid())
  userId       String
  /// grant | purchase | reserve | spend | release | refund | expire | revoke
  kind         String
  /// Signed change to the account balance (reserve/release are 0: they move `reserved`).
  delta        Int
  balanceAfter Int
  reservedAfter Int     @default(0)
  idemKey      String   @unique
  source       String?
  sourceRef    String?
  buildId      String?
  lotId        String?
  model        String?
  note         String?
  meta         Json?
  /// Admin who made a manual grant/revoke.
  actorId      String?
  createdAt    DateTime @default(now())

  @@index([userId, createdAt])
  @@index([kind, createdAt])
  @@index([sourceRef])
}

/// Tokens held for one build while it runs (keyed by the ModBuild id).
model CyrusTokenReservation {
  buildId   String    @id
  userId    String
  model     String
  amount    Int
  /// held | settled | released
  status    String    @default("held")
  charged   Int?
  costUsd   Float?
  createdAt DateTime  @default(now())
  settledAt DateTime?

  @@index([userId, status])
  @@index([status, createdAt])
}

/// The account's Cyrus plan (Stripe Billing subscription). One per account; a
/// re-subscribe after cancel replaces the row. `tier` is the PAID entitlement
/// (set from paid invoices), `priceTier` what the subscription will bill next.

import type { Metadata } from "next";
import { CyrusPage, cyrusMetadata } from "../shared";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusMetadata();
}

/** One project, focused on one version. Same preview gate (requireModBuilderUser() inside CyrusPage). */
export default async function CyrusBuild({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ retarget?: string | string[]; tab?: string | string[] }> }) {
  const { id } = await params;
  const sp = await searchParams;
  const r = sp.retarget;
  // ?retarget=<version>: "Update with Cyrus for the new version" from a creator warning.
  return CyrusPage(id, { retarget: typeof r === "string" ? r : null, tab: typeof sp.tab === "string" ? sp.tab : null });
}
