"use client";

import { CoinSpin } from "@/components/cyrus/brand/CyrusBrand";
import { useEffect, useRef, useState } from "react";
import { ModelGlyph } from "@/components/cyrus/icons/ModelGlyphs";
import { ThinkingBrain } from "@/components/cyrus/icons/ThinkingBrain";
import { CheckIcon, ChevronDownIcon, CloseIcon, CodeIcon } from "@/components/cyrus/icons/ui";
import { MODEL_BY_ID } from "@/lib/cyrus/data";
import { jobRouteLabel } from "@/lib/cyrus/forge";
import { getGame, isJobLive, useStore, type Job, type ThinkItem } from "@/lib/cyrus/store";

/** Reveals text character-by-character, like it's being thought. */
function TypeText({ text, speed = 14 }: { text: string; speed?: number }) {
  const [n, setN] = useState(0);
  useEffect(() => {
    setN(0);
    const id = window.setInterval(() => {
      setN((v) => {
        if (v >= text.length) {
          window.clearInterval(id);
          return v;
        }
        return v + 2;
      });
    }, speed);
    return () => window.clearInterval(id);
  }, [text, speed]);
  return <>{text.slice(0, n)}</>;
}

function Spinner() {
  return (
    <span className="relative grid h-4 w-4 place-items-center">
      <span className="absolute inset-0 rounded-full border border-cy-accent/25" />
      <span className="absolute inset-0 animate-spin rounded-full border border-transparent border-t-cy-cyan" />
      <span className="h-1 w-1 rounded-full bg-cy-cyan shadow-[0_0_6px_var(--cyan)]" />
    </span>
  );
}

function StepRow({ s, job, last }: { s: ThinkItem; job: Job; last: boolean }) {
  const file = s.id.startsWith("w") ? job.files.find((f) => f.path === s.detail) : undefined;
  const lines = file ? file.content.split("\n").length : 0;
  return (
    <li className="animate-rise flex items-start gap-2.5 py-[5px]">
      <span className="mt-[1px] shrink-0">
        {s.done ? (
          <span className="grid h-4 w-4 place-items-center rounded-full bg-cy-accent/15 text-[10px] text-cy-accent">
            <CheckIcon />
          </span>
        ) : (
          <Spinner />
        )}
      </span>
      <span className="min-w-0 flex-1">
        <span className={`block text-[12.5px] font-medium ${s.done ? "text-cy-ink-2" : last ? "shimmer-text" : "text-cy-ink"}`}>{s.label}</span>
        {s.detail && (
          <span className="block truncate font-mono text-[11px] text-cy-muted">
            {s.done ? s.detail : <TypeText text={s.detail} />}
            {file && !s.done && <span className="ml-2 text-cy-cyan">{lines} lines</span>}
    );
  }

  return (
    <div className="cy5-glass animate-rise hairline-top mb-2.5 overflow-hidden rounded-2xl">
      <button type="button" onClick={() => setOpen((o) => !o)} className="flex w-full items-center gap-3 px-3.5 py-2.5 text-left">
        <span className="think-badge" aria-hidden>
          <ThinkingBrain />
        </span>
        <div className="min-w-0 flex-1">
          <div className="shimmer-text font-cy-display text-[13px] font-semibold">
            {job.status === "writing" ? "Cyrus is writing code" : job.status === "connecting" ? "Waking the core" : "Cyrus is thinking"}
          </div>
          <div className="truncate text-[11px] text-cy-muted">{route ? `Cyrus Core › ${route}` :"Routing your idea through the network…"}</div>
        </div>
        <span className="tint flex items-center gap-1.5 rounded-lg px-2 py-1 text-[11px] text-cy-ink-2" style={{ ["--c" as string]: model.rgb, background: `rgb(${model.rgb} / 0.1)` }}>
          <ModelGlyph id={model.id} size={15} />
          {model.name}
        </span>
        {job.real && job.credits > 0 && (
          <span className="hidden items-center gap-1 text-[11px] tabular-nums text-cy-muted sm:inline-flex" title="Tokens held while this build runs. It only spends what it uses.">
            <CoinSpin size={16} /> {job.credits.toLocaleString("en-US")} held
          </span>
        )}
        <span className="w-11 text-right font-mono text-[11px] tabular-nums text-cy-muted">{elapsed}s</span>
        <ChevronDownIcon className={`text-cy-muted transition ${open ? "" : "-rotate-90"}`} />
      </button>
      <div className="relative h-[2px] overflow-hidden bg-[rgb(var(--glow)/0.08)]">
        <div className="absolute inset-y-0 w-1/3 bg-gradient-to-r from-transparent via-cy-cyan to-transparent" style={{ animation: "cy5-progress-sheen 1.3s ease-in-out infinite" }} />
      </div>
      {open && (
        <ul
          ref={listRef}
          className="max-h-[188px] overflow-y-auto px-3.5 py-2"
          style={{ maskImage: "linear-gradient(180deg, transparent 0, #000 14px, #000 100%)" }}
        >
          {job.steps.map((s, i) => (
            <StepRow key={s.id} s={s} job={job} last={i === job.steps.length - 1} />
          ))}
          {job.steps.length === 0 && (
            <li className="flex items-center gap-2.5 py-1.5 text-[12.5px]">
              <Spinner />
              <span className="shimmer-text">Opening a channel to the core…</span>
            </li>
          )}
        </ul>
      )}
    </div>
  );
}

