/**
 * Cyrus plan/model sigils (v7, from the cyrus.my landing's plans section): Katara a water wave, Saka a cool blue
 * flame, Yakko an arcane sigil with a spark. Plain strings, no React: components/cyrus/icons/ModelGlyphs.tsx renders
 * them and scripts/cyrus/model-sigil-files.ts writes the same markup to public/cyrus/models/*.svg.
 *
 *  - sigil (96 grid): the brand version, ring + dark disc + motif. `animated` adds the landing's motion (waves drift,
 *    flame flickers, rings turn); static is the default and the reduced-motion fallback.
 *  - mono (24 grid): currentColor line art of the same motif for tight UI (chips, rows, 12-16 px).
 */
export type SigilId = "katara" | "saka" | "yakko";
export const SIGIL_IDS: SigilId[] = ["katara", "saka", "yakko"];
export const SIGIL_LABEL: Record<SigilId, string> = { katara: "Katara: a water wave", saka: "Saka: a cool blue flame", yakko: "Yakko: an arcane sigil with a spark" };
/** The tint each plan card uses (landing --tint). */
export const SIGIL_TINT: Record<SigilId, string> = { katara: "#3d7bff", saka: "#6a6cff", yakko: "#8b5cff" };

const WAVE = (y: number, a: number) => `M0 ${y} Q12 ${y - a} 24 ${y} T48 ${y} T72 ${y} T96 ${y} T120 ${y} T144 ${y}`;
const FLAME_OUT = "M48 16C58 30 70 40 68 57C66 72 58 80 48 80C36 80 28 72 28 59C28 47 36 41 40 31C42 41 46 45 50 45C50 35 46 26 48 16Z";
const FLAME_MID = "M48 36C55 45 60 53 59 63C58 72 54 78 48 78C41 78 37 72 37 65C37 57 42 53 44 47C46 53 48 55 50 55C51 49 49 42 48 36Z";
const FLAME_CORE = "M48 53C52 59 54 64 54 69C54 75 51 78 48 78C45 78 42 75 42 71C42 65 46 61 48 53Z";
const SPARK = "M48 36L50.6 45.4L60 48L50.6 50.6L48 60L45.4 50.6L36 48L45.4 45.4Z";

/** Motion, scoped by the per-instance prefix `p` so two copies never share keyframes or ids. */
function motion(p: string): string {
  return `<style>
.${p} .w1{animation:${p}wave 5s linear infinite}.${p} .w2{animation:${p}wave 3.4s linear infinite reverse}.${p} .w3{animation:${p}wave 7s linear infinite}
.${p} .bob{animation:${p}bob 4s ease-in-out infinite}
.${p} .fl1{transform-origin:48px 78px;animation:${p}flick 2.2s ease-in-out infinite}.${p} .fl2{transform-origin:48px 78px;animation:${p}flick 1.7s ease-in-out infinite reverse}.${p} .fl3{transform-origin:48px 78px;animation:${p}flick 1.3s ease-in-out infinite}
.${p} .em{animation:${p}rise 2.6s ease-in infinite;opacity:0}.${p} .em2{animation-delay:.9s}.${p} .em3{animation-delay:1.7s}
.${p} .r1{transform-origin:48px 48px;animation:${p}rot 18s linear infinite}.${p} .r2{transform-origin:48px 48px;animation:${p}rot 12s linear infinite reverse}
.${p} .spark{transform-origin:48px 48px;animation:${p}spark 2.8s ease-in-out infinite}
@keyframes ${p}wave{to{transform:translateX(-48px)}}@keyframes ${p}bob{50%{transform:translateY(-2px)}}
@keyframes ${p}flick{0%,100%{transform:scale(1,1) skewX(0)}30%{transform:scale(.97,1.05) skewX(-3deg)}65%{transform:scale(1.03,.96) skewX(3deg)}}
@keyframes ${p}rise{0%{transform:translateY(0);opacity:0}20%{opacity:1}100%{transform:translateY(-34px);opacity:0}}
@keyframes ${p}rot{to{transform:rotate(360deg)}}
@keyframes ${p}spark{0%,100%{transform:scale(.86) rotate(0);opacity:.85}50%{transform:scale(1.08) rotate(45deg);opacity:1}}
@media (prefers-reduced-motion:reduce){.${p} *{animation:none!important}.${p} .em{opacity:.8}}
</style>`;
}

/** Inner markup of the 96-grid sigil. `p` prefixes every id (and the motion classes' scope). */
export function sigilInner(id: SigilId, p: string, animated = false): string {
  const m = animated ? motion(p) : "";
  if (id === "katara") {
    return `${m}<defs><linearGradient id="${p}g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9cc0ff"/><stop offset="1" stop-color="#2a5cff"/></linearGradient><linearGradient id="${p}r" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff"/><stop offset="1" stop-color="#3d7bff" stop-opacity=".3"/></linearGradient><clipPath id="${p}c"><circle cx="48" cy="48" r="38"/></clipPath></defs>`
      + `<circle cx="48" cy="48" r="44" fill="none" stroke="url(#${p}r)" stroke-width="1.5"/><circle cx="48" cy="48" r="38" fill="#05070f"/>`
      + `<g clip-path="url(#${p}c)"><g class="w3"><path d="${WAVE(62, 6)} V96 H0Z" fill="#1d3fb8" opacity=".55"/></g><g class="w2"><path d="${WAVE(54, 8)} V96 H0Z" fill="url(#${p}g)" opacity=".7"/></g>`
      + `<g class="w1"><path d="${WAVE(60, 10)} V96 H0Z" fill="url(#${p}g)"/><path d="${WAVE(60, 10)}" fill="none" stroke="#fff" stroke-width="1.6" stroke-linecap="round"/></g></g>`
      + `<g class="bob"><circle cx="34" cy="34" r="2.4" fill="#fff"/><circle cx="42" cy="28" r="1.3" fill="#cfe0ff"/></g>`;
  }
  if (id === "saka") {
