/** The tint each plan card uses (landing --tint). */
export const SIGIL_TINT: Record<SigilId, string> = { katara: "#3d7bff", saka: "#6a6cff", yakko: "#8b5cff" };

const WAVE = (y: number, a: number) => `M0 ${y} Q12 ${y - a} 24 ${y} T48 ${y} T72 ${y} T96 ${y} T120 ${y} T144 ${y}`;
const FLAME_OUT = "M48 16C58 30 70 40 68 57C66 72 58 80 48 80C36 80 28 72 28 59C28 47 36 41 40 31C42 41 46 45 50 45C50 35 46 26 48 16Z";
const FLAME_MID = "M48 36C55 45 60 53 59 63C58 72 54 78 48 78C41 78 37 72 37 65C37 57 42 53 44 47C46 53 48 55 50 55C51 49 49 42 48 36Z";
const FLAME_CORE = "M48 53C52 59 54 64 54 69C54 75 51 78 48 78C45 78 42 75 42 71C42 65 46 61 48 53Z";
