.${p} .em{animation:${p}rise 2.6s ease-in infinite;opacity:0}.${p} .em2{animation-delay:.9s}.${p} .em3{animation-delay:1.7s}
.${p} .r1{transform-origin:48px 48px;animation:${p}rot 18s linear infinite}.${p} .r2{transform-origin:48px 48px;animation:${p}rot 12s linear infinite reverse}
.${p} .spark{transform-origin:48px 48px;animation:${p}spark 2.8s ease-in-out infinite}
