"use client";

import { useEffect, useState, type JSX, type SVGProps } from "react";
import type { ModelId } from "@/lib/cyrus/types";
import { MONO_INNER, SIGIL_LABEL, sigilInner } from "./modelSigils";

/**
 * Cyrus plan/model glyphs (v7, the cyrus.my landing's plan icons): Katara a water wave, Saka a cool blue flame,
 * Yakko an arcane sigil with a spark. Markup lives in ./modelSigils.ts (shared with public/cyrus/models/*.svg).
 *
 *  - variant "gradient" (default): the full-colour sigil. Static unless `animated` (plan cards, pickers, marketing);
 *    reduced motion always gets the static one.
 *  - variant "mono": currentColor line art on a 24 grid for tight UI (chips, rows, locked states).
 *
 * Files: public/cyrus/models/{id}.svg (static), {id}-animated.svg, {id}-mono.svg (scripts/cyrus/model-sigil-files.ts).
 */

let seq = 0;

export type ModelGlyphVariant = "gradient" | "mono";
type P = Omit<SVGProps<SVGSVGElement>, "id"> & { size?: number | string; variant?: ModelGlyphVariant; title?: string; animated?: boolean };

/** Renders the mark for a Cyrus model. Size defaults to 1em, like the other studio icons. */
export function ModelGlyph({ id, size = "1em", variant = "gradient", title, animated = false, className, ...props }: { id: ModelId } & P) {
  const sid = id in MONO_INNER ? id : "saka";
  // A stable prefix for the server render and hydration, then a unique one per instance after mount: a shared
  // gradient id breaks every copy in Chrome when the first one sits in a display:none subtree.
  const [p, setP] = useState(`cym-${sid}`);
  useEffect(() => setP(`cym-${sid}${++seq}`), [sid]);
  const mono = variant === "mono";
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={mono ? "0 0 24 24" : "0 0 96 96"}
      width={size}
      height={size}
      fill="none"
      role={title ? "img" : undefined}
      aria-label={title ?? undefined}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={`cy-model-glyph ${mono ? "" : p} ${className ?? ""}`}
      data-model={sid}
      data-variant={variant}
      data-animated={!mono && animated ? "" : undefined}
      dangerouslySetInnerHTML={{ __html: mono ? MONO_INNER[sid] : sigilInner(sid, p, animated) }}
      {...props}
    />
  );
}

export const MODEL_GLYPH_LABEL = SIGIL_LABEL;
export const KataraGlyph = (p: P) => <ModelGlyph id="katara" {...p} />;
export const SakaGlyph = (p: P) => <ModelGlyph id="saka" {...p} />;
export const YakkoGlyph = (p: P) => <ModelGlyph id="yakko" {...p} />;
export const MODEL_GLYPHS: Record<ModelId, (p: P) => JSX.Element> = { katara: KataraGlyph, saka: SakaGlyph, yakko: YakkoGlyph };

