// Cyrus token spend, read side: the live meter of a running build and the spend breakdown of a mod (every version,
// change and asset build of one project). Server only; reads the reservation + ledger the economy already writes.
//
// Honest numbers:
//  - "estimated": tokensForCost(the AI usage the builder has reported so far). It moves while the build runs and is
//    NOT a charge; the account only ever pays what settle decides.
//  - "settled": the ledger's settle row (charged, returned to the balance, and what Nxeon wrote off).
import type { Prisma } from "@prisma/client";
import { cyrusDb as db } from "../db";
import { isCyrusModel, type CyrusModelId } from "../models";
import { readCyrusMeta } from "../meta";
import { loadTokenConfig, type TokenConfig } from "./config";
import { tokensForCost } from "./economy";

export type SpendState = "running" | "settled" | "released" | "untracked";

export type BuildSpend = {
  buildId: string;
  model: CyrusModelId;
  state: SpendState;
  /** Tokens held when it started (0 = untracked or not reserved). */
  held: number;
  /** From the AI usage reported so far; an estimate, never a charge. */
  estimated: number;
  /** Final figures once settled (null while running). */
  charged: number | null;
  returned: number | null;
  writeoff: number;
  reason: string | null;
  settledAt: string | null;
};

type Res = { amount: number; status: string; charged: number | null; model: string; settledAt: Date | null } | null;
type Build = { id: string; status: string; costUsd: number; cyrus: Prisma.JsonValue | null };
type Settle = { delta: number; note: string | null; meta: Prisma.JsonValue | null; createdAt: Date } | null;

const TERMINAL = new Set(["succeeded", "failed"]);

/** Pure: one build's spend from its rows. */
export function buildSpendFrom(b: Build, res: Res, settle: Settle, cfg: TokenConfig): BuildSpend {
  const model: CyrusModelId = res && isCyrusModel(res.model) ? res.model : (readCyrusMeta(b.cyrus).model ?? "saka");
  const estimated = tokensForCost(b.costUsd || 0, model, cfg);
  if (!res) return { buildId: b.id, model, state: "untracked", held: 0, estimated, charged: null, returned: null, writeoff: 0, reason: null, settledAt: null };
  if (res.status === "held") return { buildId: b.id, model, state: TERMINAL.has(b.status) ? "running" : "running", held: res.amount, estimated, charged: null, returned: null, writeoff: 0, reason: null, settledAt: null };
  const m = (settle?.meta ?? {}) as { released?: number; writeoff?: number };
  const charged = res.charged ?? Math.max(0, -(settle?.delta ?? 0));
  return {
    buildId: b.id, model, state: res.status === "settled" ? "settled" : "released", held: res.amount, estimated,
    charged, returned: typeof m.released === "number" ? m.released : Math.max(0, res.amount - charged), writeoff: typeof m.writeoff === "number" ? m.writeoff : 0,
    reason: settle?.note ?? null, settledAt: (res.settledAt ?? settle?.createdAt)?.toISOString() ?? null,
  };
}

async function load(userId: string, builds: Build[]): Promise<BuildSpend[]> {
  if (!builds.length) return [];
  const ids = builds.map((b) => b.id);
  const [cfg, res, settles] = await Promise.all([
    loadTokenConfig(),
    db.cyrusTokenReservation.findMany({ where: { buildId: { in: ids }, userId }, select: { buildId: true, amount: true, status: true, charged: true, model: true, settledAt: true } }),
    db.cyrusTokenLedger.findMany({ where: { userId, idemKey: { in: ids.map((i) => `settle:${i}`) } }, select: { buildId: true, delta: true, note: true, meta: true, createdAt: true } }),
  ]);
  const r = new Map(res.map((x) => [x.buildId, x]));
  const s = new Map(settles.map((x) => [x.buildId, x]));
  return builds.map((b) => buildSpendFrom(b, r.get(b.id) ?? null, s.get(b.id) ?? null, cfg));
}

/** The live meter for one of the user's builds (null = not theirs). */
export async function liveBuildSpend(userId: string, buildId: string): Promise<BuildSpend | null> {
  const b = await db.modBuild.findUnique({ where: { id: buildId }, select: { id: true, userId: true, status: true, costUsd: true, cyrus: true } });
  if (!b || b.userId !== userId) return null;
  return (await load(userId, [b]))[0];
}

export type SpendRow = BuildSpend & { seq: number; kind: "first build" | "change" | "asset" | "revert"; label: string; status: string; createdAt: string };
export type ModSpend = {
  rootId: string;
  rows: SpendRow[];
  total: { charged: number; returned: number; writeoff: number; running: number; estimatedRunning: number; builds: number };
};

const ASSET_KINDS = new Set(["asset", "assets", "texture", "sound", "model", "designer", "datapack"]);

/** Pure: totals + per-row kind/label for a mod's builds (oldest first). */
export function modSpendFrom(rootId: string, builds: (Build & { createdAt: Date; changeRequest: string | null; prompt: string; baseBuildId: string | null })[], spend: BuildSpend[], revKind: Map<string, string>): ModSpend {
  const rows: SpendRow[] = builds.map((b, i) => {
    const rk = revKind.get(b.id) ?? "";
    const kind: SpendRow["kind"] = rk === "revert" ? "revert" : ASSET_KINDS.has(rk) ? "asset" : b.baseBuildId ? "change" : "first build";
    const text = (b.changeRequest || b.prompt || "").replace(/\s+/g, " ").trim();
    return { ...spend[i], seq: i + 1, kind, label: text.length > 90 ? `${text.slice(0, 87)}...` : text, status: b.status, createdAt: b.createdAt.toISOString() };
  });
  const total = { charged: 0, returned: 0, writeoff: 0, running: 0, estimatedRunning: 0, builds: rows.length };
  for (const r of rows) {
    total.charged += r.charged ?? 0;
    total.returned += r.returned ?? 0;
    total.writeoff += r.writeoff;
    if (r.state === "running") { total.running++; total.estimatedRunning += r.estimated; }
  }
  return { rootId, rows, total };
}

/** Spend breakdown of one of the user's mods: `anyBuildId` may be the root or any version of it. */
export async function modSpend(userId: string, anyBuildId: string): Promise<ModSpend | null> {
  const b = await db.modBuild.findUnique({ where: { id: anyBuildId }, select: { userId: true, id: true, rootBuildId: true } });
  if (!b || b.userId !== userId) return null;
  const rootId = b.rootBuildId ?? b.id;
  const builds = await db.modBuild.findMany({
    where: { userId, OR: [{ id: rootId }, { rootBuildId: rootId }] },
    orderBy: { createdAt: "asc" },
    take: 500,
    select: { id: true, status: true, costUsd: true, cyrus: true, createdAt: true, changeRequest: true, prompt: true, baseBuildId: true },
  });
  const revs = await db.cyrusRevision.findMany({ where: { modBuildId: { in: builds.map((x) => x.id) } }, select: { modBuildId: true, kind: true } });
  const revKind = new Map(revs.filter((r) => r.modBuildId).map((r) => [r.modBuildId as string, r.kind]));
  return modSpendFrom(rootId, builds, await load(userId, builds), revKind);
}

