"use client";

import { useEffect, useRef, useState } from "react";
import { ModelGlyph } from "@/components/cyrus/icons/ModelGlyphs";
import type { BuildSpend, ModSpend } from "@/lib/cyrus/tokens/spend";
import "./spend.css";

/**
 * r41 token spend UI: the live meter in the build screen, a one-line summary for a finished build, and the per-mod
 * breakdown. Reads GET /api/cyrus/tokens/spend (own builds only). "Estimated" is the AI usage reported so far, not a
 * charge; "spent" is what settle charged. Renders nothing for builds outside the token economy.
 */

const n = (v: number) => Math.round(v).toLocaleString("en-US");

const REASON: Record<string, string> = {
  succeeded: "Charged for the work it did",
  failed_free: "Failed on our side: no charge",
  failed_partial: "Failed: only part charged",
  failed_over_limit: "Failed after the free retries: charged",
  refused: "Refused: no charge",
  cancelled: "Cancelled",
  not_started: "Never started: all returned",
  stale: "Lost contact: all returned",
};
export const spendReason = (r: string | null) => (r ? REASON[r] ?? r : "");

async function getJson<T>(q: string): Promise<T | null> {
  const r = await fetch(`/api/cyrus/tokens/spend?${q}`, { cache: "no-store" }).catch(() => null);
  return r && r.ok ? ((await r.json()) as T) : null;
}

function useBuildSpend(buildId: string | undefined, live: boolean): BuildSpend | null {
  const [s, setS] = useState<BuildSpend | null>(null);
  const wasLive = useRef(live);
  useEffect(() => {
    if (!buildId) return;
    let stop = false;
    let t: number | undefined;
    const tick = async (left: number) => {
      const j = await getJson<BuildSpend>(`build=${encodeURIComponent(buildId)}`);
      if (stop) return;
      if (j) setS(j);
      const settled = j && j.state !== "running" && j.state !== "settling";
      // while live: every 3 s (9 s in a background tab); after it ends: a few more until the ledger settles
      if (live || (!settled && left > 0)) t = window.setTimeout(() => void tick(live ? left : left - 1), live ? (document.visibilityState === "hidden" ? 9000 : 3000) : 2000);
    };
    void tick(wasLive.current && !live ? 6 : 3);
    wasLive.current = live;
    return () => { stop = true; window.clearTimeout(t); };
  }, [buildId, live]);
  return s;
}

/** Build screen: estimated so far vs held while it runs, then the settled result. */
export function LiveSpendMeter({ buildId, live }: { buildId?: string; live: boolean }) {
  const s = useBuildSpend(buildId, live);
  if (!s || s.state === "untracked") return null;
  const running = s.state === "running" || s.state === "settling";
  const pct = s.held > 0 ? Math.min(100, (s.estimated / s.held) * 100) : 0;
  return (
    <div className="cys-meter" data-state={s.state} aria-live="polite">
      <div className="cys-meter-top">
        <span className="cys-k">Tokens</span>
        {running ? (
          <span className="cys-v">
            <b title="From the AI work reported so far. Not a charge: the build is settled when it ends.">≈ {n(s.estimated)}</b> so far <span className="cys-est">estimated</span>
            <span className="cys-of"> of {n(s.held)} held</span>
          </span>
        ) : (
          <span className="cys-v">
            <b>{n(s.charged ?? 0)}</b> spent <span className="cys-set">settled</span>
            {(s.returned ?? 0) > 0 && <span className="cys-of"> · {n(s.returned ?? 0)} returned to your balance</span>}
            {s.writeoff > 0 && <span className="cys-of"> · {n(s.writeoff)} covered by Cyrus</span>}
          </span>
        )}
      </div>
      <div className="cys-bar" role="meter" aria-valuemin={0} aria-valuemax={s.held} aria-valuenow={running ? s.estimated : s.charged ?? 0} aria-label="Tokens used of the tokens held">
        <span className={running ? "cys-fill cys-fill-live" : "cys-fill"} style={{ width: `${running ? pct : s.held > 0 ? Math.min(100, ((s.charged ?? 0) / s.held) * 100) : 0}%` }} />
      </div>
      <div className="cys-fine">
        {running
          ? s.state === "settling" ? "Finishing up: settling the final charge..." : "You only pay for the work this build does. Whatever it doesn't use goes back to your balance."
          : spendReason(s.reason)}
      </div>
    </div>
  );
}

/** One line for a finished build (build detail). */
export function BuildSpendLine({ buildId }: { buildId?: string }) {
  const s = useBuildSpend(buildId, false);
  if (!s || s.state === "untracked") return null;
  if (s.state === "running" || s.state === "settling") return <span className="cys-line">Tokens: ≈ {n(s.estimated)} so far (estimated), {n(s.held)} held</span>;
  return (
    <span className="cys-line" title={spendReason(s.reason)}>
      Tokens: <b>{n(s.charged ?? 0)}</b> spent of {n(s.held)} held{(s.returned ?? 0) > 0 ? `, ${n(s.returned ?? 0)} returned` : ""}{s.writeoff > 0 ? `, ${n(s.writeoff)} covered by Cyrus` : ""}
    </span>
  );
}

const KIND_LABEL: Record<string, string> = { "first build": "First build", change: "Change", asset: "Asset", import: "Import", revert: "Revert" };

/** Project page / versions: total spend for the mod and every build behind it. */
export function ModSpendPanel({ buildId, refreshKey }: { buildId?: string; refreshKey?: string | number }) {
  const [m, setM] = useState<ModSpend | null>(null);
  useEffect(() => {
    if (!buildId) return;
    let stop = false;
    void getJson<ModSpend>(`mod=${encodeURIComponent(buildId)}`).then((j) => { if (!stop && j) setM(j); });
    return () => { stop = true; };
  }, [buildId, refreshKey]);
  if (!m || !m.rows.some((r) => r.state !== "untracked")) return null;
  const max = Math.max(1, ...m.rows.map((r) => r.charged ?? r.estimated));
  const rows = [...m.rows].reverse();
  return (
    <section className="cys-mod" aria-labelledby="cys-mod-h">
      <div className="cys-mod-head">
        <div>
          <h3 id="cys-mod-h">Token spend for this mod</h3>
          <p className="cys-fine">
            {m.total.builds} build{m.total.builds === 1 ? "" : "s"} · {n(m.total.returned)} returned to your balance
            {m.total.writeoff > 0 ? ` · ${n(m.total.writeoff)} covered by Cyrus` : ""}
            {m.total.running > 0 ? ` · ≈ ${n(m.total.estimatedRunning)} estimated in progress` : ""}
          </p>
        </div>
        <div className="cys-total"><b>{n(m.total.charged)}</b><span>spent</span></div>
      </div>
      <div className="cys-table" role="table" aria-label="Tokens per build">
        <div className="cys-tr cys-th" role="row">
          <span role="columnheader">#</span><span role="columnheader">Build</span><span role="columnheader" className="cys-hide-s">Held</span><span role="columnheader">Spent</span><span role="columnheader" className="cys-hide-s">Returned</span>
        </div>
        {rows.map((r) => {
          const live = r.state === "running" || r.state === "settling";
          const v = live ? r.estimated : r.charged ?? 0;
          return (
            <div key={r.buildId} className="cys-tr" role="row" data-state={r.state}>
              <span role="cell" className="cys-seq">v{r.seq}</span>
              <span role="cell" className="cys-what">
                <span className="cys-what-t"><ModelGlyph id={r.model} size={13} /><span className="cys-kind">{KIND_LABEL[r.kind] ?? r.kind}</span><span className="cys-lbl" title={r.label}>{r.label || "Untitled"}</span></span>
                <span className="cys-spark" aria-hidden><span style={{ width: `${(v / max) * 100}%` }} className={live ? "cys-fill-live" : ""} /></span>
                <span className="cys-why">{r.state === "untracked" ? "Before tokens" : live ? "Running: estimate" : spendReason(r.reason)}</span>
              </span>
              <span role="cell" className="cys-num cys-hide-s">{r.state === "untracked" ? "-" : n(r.held)}</span>
              <span role="cell" className="cys-num"><b>{r.state === "untracked" ? "-" : live ? `≈ ${n(v)}` : n(v)}</b></span>
              <span role="cell" className="cys-num cys-hide-s">{live || r.state === "untracked" ? "-" : n(r.returned ?? 0)}</span>
            </div>
          );
        })}
      </div>
      <p className="cys-fine">Each build holds tokens when it starts and only spends what it uses; the rest comes back the moment it finishes. Failed builds on our side are free (a few a week), refused or cancelled builds are not charged.</p>
    </section>
  );
}

