import { tokensForCost } from "../lib/cyrus/tokens/economy";

describe("r41 token spend (E)", () => {
  const cfg = parseTokenConfig({});
  const b = (id: string, status: string, costUsd: number) => ({ id, status, costUsd, cyrus: { model: "saka" } });
  it("running: an estimate from the reported AI usage, never a charge", () => {
    const s = buildSpendFrom(b("b1", "running", 0.2), { amount: 900, status: "held", charged: null, model: "saka", settledAt: null }, null, cfg);
    assert.equal(s.state, "running");
    assert.equal(s.held, 900);
    assert.equal(s.estimated, tokensForCost(0.2, "saka", cfg));
    assert.equal(s.charged, null);
    assert.equal(s.returned, null);
  });
  it("a finished build still held is 'settling', not settled", () => {
    assert.equal(buildSpendFrom(b("b1", "succeeded", 0.2), { amount: 900, status: "held", charged: null, model: "saka", settledAt: null }, null, cfg).state, "settling");
  });
  it("settled: charged, returned and write-off come from the reservation + settle row", () => {
    const s = buildSpendFrom(b("b1", "succeeded", 0.2), { amount: 900, status: "settled", charged: 300, model: "saka", settledAt: new Date("2026-10-11T10:00:00Z") },
      { delta: -300, note: "succeeded", meta: { released: 600, writeoff: 0 }, createdAt: new Date("2026-10-11T10:00:00Z") }, cfg);
    assert.deepEqual([s.state, s.charged, s.returned, s.writeoff, s.reason], ["settled", 300, 600, 0, "succeeded"]);
  });
  it("released (free failure): nothing charged, everything returned", () => {
    const s = buildSpendFrom(b("b1", "failed", 0.1), { amount: 500, status: "released", charged: 0, model: "katara", settledAt: new Date() }, { delta: 0, note: "failed_free", meta: { released: 500, writeoff: 0 }, createdAt: new Date() }, cfg);
    assert.deepEqual([s.state, s.charged, s.returned, s.model], ["released", 0, 500, "katara"]);
  });
  it("no reservation = untracked (built before tokens / outside the economy)", () => {
    assert.equal(buildSpendFrom(b("b1", "succeeded", 0.5), null, null, cfg).state, "untracked");
  });
  it("per-mod totals add settled spend, returns, write-offs and in-progress estimates; kinds follow the revision", () => {
    const at = new Date("2026-10-11T09:00:00Z");
    const builds = [
      { ...b("r", "succeeded", 0.2), createdAt: at, changeRequest: null, prompt: "A sword that sets mobs on fire", baseBuildId: null },
      { ...b("c1", "succeeded", 0.1), createdAt: at, changeRequest: "Make it blue", prompt: "x", baseBuildId: "r" },
      { ...b("c2", "running", 0.05), createdAt: at, changeRequest: "New texture", prompt: "x", baseBuildId: "c1" },
    ];
    const spend = [
      { buildId: "r", model: "saka" as const, state: "settled" as const, held: 900, estimated: 0, charged: 300, returned: 600, writeoff: 0, reason: "succeeded", settledAt: null },
      { buildId: "c1", model: "saka" as const, state: "settled" as const, held: 400, estimated: 0, charged: 150, returned: 240, writeoff: 10, reason: "succeeded", settledAt: null },
      { buildId: "c2", model: "saka" as const, state: "running" as const, held: 400, estimated: 80, charged: null, returned: null, writeoff: 0, reason: null, settledAt: null },
    ];
    const m = modSpendFrom("r", builds, spend, new Map([["c2", "asset"]]));
    assert.deepEqual(m.total, { charged: 450, returned: 840, writeoff: 10, running: 1, estimatedRunning: 80, builds: 3 });
    assert.deepEqual(m.rows.map((r) => [r.seq, r.kind]), [[1, "first build"], [2, "change"], [3, "asset"]]);
    assert.equal(m.rows[1].label, "Make it blue");
  });
  it("the spend API is own-builds only and read only; the meter and breakdown are mounted", () => {
    const route = readFileSync("app/api/cyrus/tokens/spend/route.ts", "utf8");
    assert.match(route, /modBuilderUser\(\)/);
    assert.match(route, /liveBuildSpend\(user\.id, id\)/);
    assert.doesNotMatch(route, /export async function (POST|PUT|PATCH|DELETE)/);
    const lib = readFileSync("lib/cyrus/tokens/spend.ts", "utf8");
    assert.match(lib, /b\.userId !== userId\) return null/);
    assert.match(readFileSync("components/cyrus/prompt/ThinkingTrace.tsx", "utf8"), /<LiveSpendMeter buildId=\{job\.buildId\} live \/>/);
    assert.match(readFileSync("components/cyrus/preview/VersionsTab.tsx", "utf8"), /<ModSpendPanel /);
    assert.match(readFileSync("components/cyrus/preview/ExplainTab.tsx", "utf8"), /<BuildSpendLine buildId=\{b\.id\} \/>/);
    assert.match(readFileSync("components/cyrus-tokens/Spend.tsx", "utf8"), /estimated/);
  });
});
