// CYRUS SIDE: what each Nxeon -> Cyrus event does. Every handler is idempotent (events are at-least-once and carry
// current state). HOST SEAM: no platform imports (Nxeon is reached through getHost()).
import { cyrusDb as db } from "../db";
import type { PlatformEventHandlers, PlatformEventIn } from "./platform-events";

const str = (e: PlatformEventIn, k: string) => (typeof e.data[k] === "string" ? (e.data[k] as string) : null);
const revoked = new Map<string, number>();
/** Grants Nxeon told us were revoked (serverId:userId), so Cyrus' UI stops offering them before the next list call. */
export const wasRevoked = (serverId: string, userId: string) => revoked.has(`${serverId}:${userId}`);

/** server.version_changed: the mods on that server built for another version line are marked OUTDATED for their creator
 *  (CyrusCreatorAlert SERVERS_AHEAD, the same row the compat watch keeps, so the two never duplicate). */
export async function onServerVersionChanged(e: PlatformEventIn): Promise<{ outdated: number }> {
  const serverId = str(e, "serverId"), to = str(e, "to");
  if (!serverId || !to) return { outdated: 0 };
  const [{ lifecycleForServer }, { versionLine }] = await Promise.all([import("../lifecycle/server"), import("../lifecycle/compat")]);
  const rows = await lifecycleForServer(serverId).catch(() => []);
  let n = 0;
  for (const r of rows) {
    // the lifecycle view already compares the server's (new) version with the build's: "outdated" = game ahead / newer build
    if (r.view.state !== "outdated") continue;
    const root = await db.modBuild.findUnique({ where: { id: r.rootBuildId }, select: { userId: true } });
    if (!root) continue;
    const key = `SERVERS_AHEAD:minecraft:${versionLine(to)}`;
    await db.cyrusCreatorAlert.upsert({
      where: { rootBuildId_key: { rootBuildId: r.rootBuildId, key } },
      create: { userId: root.userId, rootBuildId: r.rootBuildId, kind: "SERVERS_AHEAD", key, gameId: "minecraft", targetVersion: to, buildable: false, title: `${r.name}: a server moved to Minecraft ${to}`, body: `A server running ${r.name} was updated to Minecraft ${to}. Rebuild the mod for ${versionLine(to)} so it keeps working there.`, servers: 1 },
      update: { lastSeenAt: new Date(), resolvedAt: null },
    });
    n++;
  }
  return { outdated: n };
}

export function platformEventHandlers(): PlatformEventHandlers {
  return {
    "entitlement.changed": async (e) => (await import("../tokens/entitlement")).applyEntitlement(e.data),
    "server.version_changed": onServerVersionChanged,
    // the server is gone: Cyrus' managed-plugin references to it go too (nothing left to hold them)
    "server.deleted": async (e) => {
      const serverId = str(e, "serverId");
      if (!serverId) return { removed: 0 };
      if (e.subject) revoked.set(`${serverId}:${e.subject}`, Date.now());
      return { removed: (await db.cyrusServerManagedPlugin.deleteMany({ where: { serverId } })).count };
    },
    "grant.revoked": async (e) => { const s = str(e, "serverId"); if (s && e.subject) revoked.set(`${s}:${e.subject}`, Date.now()); return { ok: true }; },
    "grant.created": async (e) => { const s = str(e, "serverId"); if (s && e.subject) revoked.delete(`${s}:${e.subject}`); return { ok: true }; },
    "grant.updated": async () => ({ ok: true }),
    "server.restarted": async () => ({ ok: true }),
  };
}
