// ---------------------------------------------------------------------------------------------------------------
// (F) plan rollover / lapse rules + free server tokens
// ---------------------------------------------------------------------------------------------------------------
import { lapseExpiry, planActive, planGrantExpiry, planTokensFrozen, rolloverRoom, rolloverRulesCopy, serverGrantRulesCopy } from "../lib/cyrus/tokens/rollover";
import { CYRUS_TOKEN_DEFAULTS, TOKEN_PLACEHOLDER_KEYS } from "../lib/cyrus/tokens/config";
import { PLATFORM_EVENT_TYPES, serverPurchased, serverRefunded, serverRenewed } from "../lib/nxeon-platform/events";

describe("r41 token rules (F)", () => {
  const DAY = 86_400_000;
  const now = new Date("2026-10-11T12:00:00Z");
  const cfg = parseTokenConfig({});
  const with_ = (o: Record<string, string>) => parseTokenConfig(o);
  it("defaults: roll over while active, freeze then expire after 30 days, no cap; all r41 amounts flagged as placeholders", () => {
    assert.equal(cfg.plan.rolloverMode, "while_active");
    assert.equal(cfg.plan.lapseRule, "freeze_then_expire");
    assert.equal(cfg.plan.rolloverCapMonths, 0);
    assert.equal(cfg.grant.scope, "cyrus_games");
    for (const k of ["cyrus_tok_grant_scope", "cyrus_tok_grant_per_server_cap", "cyrus_tok_grant_clawback_days", "cyrus_tok_plan_lapse_rule", "cyrus_tok_plan_rollover_cap_months"]) assert.ok((TOKEN_PLACEHOLDER_KEYS as readonly string[]).includes(k), k);
    for (const k of TOKEN_PLACEHOLDER_KEYS) assert.ok(k in CYRUS_TOKEN_DEFAULTS, k);
  });
  it("a bad enum value falls back to the default (fail closed)", () => {
    assert.equal(with_({ cyrus_tok_plan_lapse_rule: "keep_forever" }).plan.lapseRule, "freeze_then_expire");
    assert.equal(with_({ cyrus_tok_grant_scope: "everything" }).grant.scope, "cyrus_games");
  });
  it("active = active/trialing, or past_due inside the retry grace; ended is never active", () => {
    assert.equal(planActive({ status: "active", endedAt: null, currentPeriodEnd: null }, cfg, now), true);
    assert.equal(planActive({ status: "past_due", endedAt: null, currentPeriodEnd: new Date(now.getTime() - DAY) }, cfg, now), true);
    assert.equal(planActive({ status: "past_due", endedAt: null, currentPeriodEnd: new Date(now.getTime() - 10 * DAY) }, cfg, now), false);
    assert.equal(planActive({ status: "active", endedAt: now, currentPeriodEnd: null }, cfg, now), false);
    assert.equal(planActive(null, cfg, now), false);
  });
  it("frozen only under freeze_then_expire, only for a lapsed plan", () => {
    const lapsed = { status: "canceled", endedAt: now, currentPeriodEnd: now };
    assert.equal(planTokensFrozen(lapsed, cfg, now), true);
    assert.equal(planTokensFrozen(lapsed, with_({ cyrus_tok_plan_lapse_rule: "grace_then_expire" }), now), false);
    assert.equal(planTokensFrozen({ status: "active", endedAt: null, currentPeriodEnd: null }, cfg, now), false);
    assert.equal(planTokensFrozen(null, cfg, now), false, "never subscribed: nothing to freeze");
  });
  it("expiry: none while active; the age rule is opt-in; lapse = period end (+ grace)", () => {
    assert.equal(planGrantExpiry(now, cfg), null);
    assert.equal(planGrantExpiry(now, with_({ cyrus_tok_plan_rollover_mode: "age" }))!.getTime() - now.getTime(), 93 * DAY);
    assert.equal(lapseExpiry(now, cfg).getTime() - now.getTime(), 30 * DAY);
    assert.equal(lapseExpiry(now, with_({ cyrus_tok_plan_lapse_rule: "expire" })).getTime(), now.getTime());
  });
  it("rollover cap: room for a new month never goes below zero; 0 = no cap", () => {
    assert.equal(rolloverRoom(10_000, 750, cfg), Number.POSITIVE_INFINITY);
    const c = with_({ cyrus_tok_plan_rollover_cap_months: "3" });
    assert.equal(rolloverRoom(1000, 750, c), 1250);
    assert.equal(rolloverRoom(5000, 750, c), 0);
  });
  it("the rules read the live settings in plain words", () => {
    assert.match(rolloverRulesCopy(cfg).join(" "), /roll over to the next month for as long as your plan stays active/);
    assert.match(rolloverRulesCopy(cfg).join(" "), /paused for 30 days/);
    assert.match(rolloverRulesCopy(with_({ cyrus_tok_plan_rollover_cap_months: "6" })).join(" "), /capped at 6 months/);
    assert.match(serverGrantRulesCopy(cfg).join(" "), /free tokens with every paid game server Cyrus builds for/);
    assert.match(serverGrantRulesCopy(cfg).join(" "), /deleting it within 14 days/);
  });
  it("server money events: stable ids per server/period/ref, user as subject, documented", () => {
    for (const t of ["server.purchased", "server.renewed", "server.refunded"]) assert.ok((PLATFORM_EVENT_TYPES as readonly string[]).includes(t));
    const p = serverPurchased({ userId: "u1", serverId: "s1", gameFamily: "minecraft", chargeCents: 999, termMonths: 1 });
    assert.equal(p.id, serverPurchased({ userId: "u1", serverId: "s1", gameFamily: "minecraft", chargeCents: 999, termMonths: 1 }).id);
    assert.equal(p.subject, "u1");
    const ps = new Date("2026-11-01T00:00:00Z");
    assert.match(serverRenewed({ userId: "u1", serverId: "s1", gameFamily: null, netCents: 500, months: 1, periodStart: ps }).id, new RegExp(`_${ps.getTime()}$`));
    assert.match(serverRefunded({ userId: "u1", serverId: "s1", ref: "re_1", cents: 500 }).id, /evt_srvrefund_s1_re_1/);
  });
  it("Nxeon's order, renewal (both paths) and refund code go through the one wrapper; the wrapper never throws", () => {
    assert.match(readFileSync("lib/game-order.ts", "utf8"), /await cyrusServerPurchased\(/);
    assert.match(readFileSync("lib/actions.ts", "utf8"), /await cyrusServerRenewed\(/);
    assert.match(readFileSync("worker/billing.ts", "utf8"), /await cyrusServerRenewed\(/);
    assert.match(readFileSync("lib/actions-admin-billing.ts", "utf8"), /if \(invoice\?\.serverId\) await \(await import\("\.\/nxeon-platform\/server-tokens"\)\)\.cyrusServerRefunded/);
    const w = readFileSync("lib/nxeon-platform/server-tokens.ts", "utf8");
    assert.match(w, /safeGrantPurchase/); assert.match(w, /safeGrantRenewal/); assert.match(w, /safeReverseServerGrants/);
    assert.equal((w.match(/\.catch\(\(\) => false\)/g) ?? []).length, 3);
  });
  it("the plans tab states the rules from the live settings", () => {
    const m = readFileSync("components/cyrus-tokens/TokensModal.tsx", "utf8");
    assert.match(m, /state\.rules\.plan, \.\.\.state\.rules\.servers/);
    assert.match(m, /paused until you resubscribe/);
    assert.doesNotMatch(m, /up to \{state\.rolloverMonths\} months/);
  });
});
EOF
