// r41 screenshots (run ON node-2 against `devhost dev`): Nxeon top bar, Cyrus full screen + Back to Nxeon, the live token
// meter, the per-mod breakdown, the plans tab. Dark + light, desktop + phone.
//   devhost run -- env BASE=http://127.0.0.1:<port> node scripts/cyrus/sepux-shots.mjs   (TOKENS, OUT, SHOTS=a,b)
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots/sep";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".studio-tokens.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;
async function shot(name, url, { view = "desktop", theme = "dark", wait = "body", act, clip, height } = {}) {
  if (ONLY && !ONLY.some((o) => name.includes(o))) return;
  const v = VIEW[view];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: height ?? v.height }, deviceScaleFactor: v.mobile ? 2 : 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: tok.all.token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-app-tour-v1", "done"); sessionStorage.setItem("nx-last-portal-path", "/dashboard/servers"); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  const res = await page.goto(BASE + url, { waitUntil: "load", timeout: 300000 }).catch((e) => { errs.push("goto " + e); return null; });
  await page.waitForSelector(wait, { timeout: 180000 }).catch((e) => errs.push("wait " + String(e).slice(0, 80)));
  await page.waitForTimeout(2500);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(1200);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: false, timeout: 120000, ...(clip ? { clip } : {}) }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, res ? res.status() : "-", overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}
const top = (v) => ({ x: 0, y: 0, width: VIEW[v].width, height: 90 });
for (const theme of ["dark", "light"]) {
  await shot(`sep-topbar-${theme}-desktop`, "/dashboard", { theme, wait: "[data-cyrus-entry]", clip: top("desktop") });
  await shot(`sep-topbar-${theme}-phone`, "/dashboard", { theme, view: "phone", wait: "[data-cyrus-entry]", clip: top("phone") });
  await shot(`sep-fullscreen-${theme}-desktop`, "/dashboard/cyrus", { theme, wait: "[data-cyrus-backbar]" });
  await shot(`sep-fullscreen-${theme}-phone`, "/dashboard/cyrus", { theme, view: "phone", wait: "[data-cyrus-backbar]" });
  await shot(`sep-meter-${theme}-desktop`, "/dashboard/cyrus/mbappbounty3", { theme, wait: ".cys-meter" });
  await shot(`sep-meter-${theme}-phone`, "/dashboard/cyrus/mbappbounty3", { theme, view: "phone", wait: ".cys-meter" });
  await shot(`sep-mod-${theme}-desktop`, "/dashboard/cyrus/app/projects/mbappbounty", { theme, wait: ".cys-mod", height: 1900 });
  await shot(`sep-mod-${theme}-phone`, "/dashboard/cyrus/app/projects/mbappbounty", { theme, view: "phone", wait: ".cys-mod", height: 2600, act: async (p) => { await p.locator(".cys-mod").scrollIntoViewIfNeeded(); } });
}
await shot("sep-app-fullscreen-dark-desktop", "/dashboard/cyrus/app", { wait: "[data-cyrus-backbar]" });
await shot("sep-plans-dark-desktop", "/dashboard/cyrus", { wait: ".cyt-chip", act: async (p) => { await p.locator(".cyt-chip").first().click(); await p.getByRole("tab", { name: /Plans/ }).or(p.getByRole("button", { name: /^Plans/ })).first().click(); await p.waitForSelector(".cyt-rules", { timeout: 20000 }); } });
await browser.close();
EOF
